let LISTS = structuredClone(DEFAULT_LISTS);
function registerText(value){if(typeof value==='string')return value;if(value&&typeof value==='object'&&value.ko){I18N[i18nNorm(value.ko)]={en:value.en,zh:value.zh};}return value;}
function registerListTexts(){Object.values(DEFAULT_LISTS).flat().forEach(item=>Object.values(item).forEach(registerText));}
registerListTexts();
function collectI18n(){
 document.querySelectorAll('[data-en]').forEach(el=>{
  const ko=el.textContent.replace(/\\n/g,'\n');el.textContent=ko;
  const key=i18nNorm(ko);I18N[key]={en:el.dataset.en.replace(/\\n/g,'\n'),zh:(el.dataset.zh||ko).replace(/\\n/g,'\n')};
  i18nTexts.push([el.firstChild,ko]);
 });
}
collectI18n();
const BASE_I18N = structuredClone(I18N);
function translateText(key,lang=currentLang,dict=I18N){return dict[i18nNorm(key)]?.[lang]??null;}
function t(key){return currentLang==='ko'?(KO_OVERRIDE[i18nNorm(key)]??key):(translateText(key)??KO_OVERRIDE[i18nNorm(key)]??key);}
function L(value){if(value&&typeof value==='object')return value[currentLang]||value.ko||'';return t(String(value??''));}
const tx=(ko,en,zh)=>L(tri(ko,en,zh));
function safeUrl(input){const s=String(input??'').trim();if(!s)return '';if(s.startsWith('#'))return /^#[a-z0-9-]+$/i.test(s)?s:'';try{const u=new URL(s,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function mediaUrl(url){return window.CMS_PREVIEW?.[url]||safeUrl(url);}
function el(tag,attrs={},...children){const node=document.createElement(tag);for(const [key,value] of Object.entries(attrs)){if(value==null)continue;if(key==='class')node.className=value;else if(key.startsWith('on')&&typeof value==='function')node.addEventListener(key.slice(2),value);else node.setAttribute(key,String(value));}children.flat(Infinity).forEach(child=>{if(child!=null)node.append(child instanceof Node?child:document.createTextNode(String(child)));});return node;}
function link(url,label,cls=''){const href=safeUrl(url);if(!href)return el('span',{class:cls},label);return el('a',{href,class:cls,...(!href.startsWith('#')?{target:'_blank',rel:'noopener noreferrer'}:{})},label);}
function external(key,label){return link(OFFICIAL[key],label,'button primary');}
function listNode(name,index,node){node.dataset.cmsIndex=index;return node;}
const levelLabel=n=>tx(`HSK ${n}급`,`HSK Level ${n}`,`HSK ${n}级`);
function levelMeta(item){return [item.questions&&tx(`${item.questions}문항`,`${item.questions} questions`,`${item.questions}题`),item.minutes&&(item.approx?tx(`약 ${item.minutes}분`,`About ${item.minutes} min`,`约${item.minutes}分钟`):tx(`${item.minutes}분`,`${item.minutes} min`,`${item.minutes}分钟`))].filter(Boolean).join(' · ');}
function levelCard(item,index){const meta=levelMeta(item),sections=L(item.sections);return listNode('levels',index,link('#level-'+index,[el('span',{class:'level-tier'},L(item.title)),el('strong',{class:'level-number'},levelLabel(item.number)),el('p',{class:'level-desc'},L(item.subtitle)),meta||sections?el('span',{class:'level-facts'},meta?el('span',{},meta):null,sections?el('span',{},sections):null):null],'level-card'));}
function calendarRow(item,index){return listNode('calendars',index,link(item.link,[el('span',{class:'calendar-year'},item.year),el('span',{class:'calendar-info'},el('strong',{},L(item.title)),el('span',{},L(item.description))),el('span',{class:'calendar-arrow','aria-hidden':'true'},'↗')],'calendar-row'));}
function resourceCard(item,index){const body=el('div',{},el('h3',{},L(item.title)),el('p',{},L(item.description)),link(item.file,tx('자료 열기 ↗','Open ↗','打开 ↗'),'text-link'));const cover=item.image?el('img',{class:'resource-cover',src:mediaUrl(item.image),alt:''}):el('div',{class:'resource-cover','aria-hidden':'true'},el('strong',{},'HSK'),el('span',{},L(item.thumb)||'资料'));return listNode('resources',index,el('article',{class:'resource-card'},cover,body));}
function noticeRow(item,index){return listNode('notices',index,link(item.link,[el('span',{class:'notice-badge'},L(item.badge)),el('span',{class:'notice-title'},L(item.text)),el('span',{'aria-hidden':'true'},safeUrl(item.link).startsWith('#')?'+':'↗')],'notice-row'));}
function renderSiteLists(){document.getElementById('homeLevels').replaceChildren(...LISTS.levels.map(levelCard));document.getElementById('homeCalendars').replaceChildren(...LISTS.calendars.map(calendarRow));document.getElementById('homeResources').replaceChildren(...LISTS.resources.slice(0,3).map(resourceCard));document.getElementById('homeNotices').replaceChildren(...LISTS.notices.slice(0,3).map(noticeRow));}
