const NAV_GROUP={schedule:'levels',registration:'levels',centers:'levels',results:'levels',checklist:'levels',hsk3:'levels',speaking:'levels',beginner:'resources'};
const navGroup=page=>page.startsWith('level-')?'levels':(NAV_GROUP[page]||page);
const GROUP_LABEL={levels:tri('시험 안내','Test guide','考试介绍'),resources:tri('학습 자료','Study resources','学习资料')};
const SUB_NAV={levels:[['levels',tri('급수별 안내','Levels','等级')],['speaking',tri('HSK 스피킹','HSK Speaking','HSK口语')],['schedule',tri('시험 일정','Test dates','考试日程')],['registration',tri('접수 안내','Registration','报名')],['centers',tri('고사장','Test centers','考点')],['results',tri('성적 조회','Results','成绩')],['checklist',tri('준비물','Checklist','考前准备')],['hsk3',tri('HSK 3.0','HSK 3.0','HSK 3.0')]]};
function renderSectionNav(page,title){const group=navGroup(page),items=SUB_NAV[group],sub=document.getElementById('subNav');sub.hidden=!items;if(items){sub.setAttribute('aria-label',L(GROUP_LABEL[group]));sub.replaceChildren(...items.map(([id,label])=>el('a',{href:'#'+id,...(id===page||(id==='levels'&&page.startsWith('level-'))?{'aria-current':'page'}:{})},L(label))));}else sub.replaceChildren();const crumb=document.getElementById('crumb');crumb.replaceChildren(...(GROUP_LABEL[group]&&group!==page?[link('#'+group,L(GROUP_LABEL[group])),el('span',{'aria-hidden':'true'},'/')]:[]),el('span',{},L(title)));}
function currentPage(){return location.hash.slice(1)||'home';}
function renderRoute(focus=false){const page=currentPage(),home=page==='home';document.getElementById('mainWrap').hidden=!home;document.getElementById('detailPage').hidden=home;if(!home)renderDetail(page);else document.title=tx('HSK 학습·시험 안내','HSK learning & test guide','HSK 学习与考试指南');document.querySelectorAll('#mainNav a').forEach(a=>{const active=a.hash==='#'+navGroup(page);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});closeMenu();if(focus){window.scrollTo({top:0,behavior:'instant'});if(!home)document.getElementById('detailTitle').focus({preventScroll:true});}}
function showHome(){location.hash='home';renderRoute();}
function openPage(id){location.hash=id.replace(/^#/,'');renderRoute();}
function closeMenu(){document.getElementById('mainNav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}
function setLang(lang){currentLang=['ko','en','zh'].includes(lang)?lang:'ko';document.documentElement.lang={ko:'ko',en:'en',zh:'zh-CN'}[currentLang];try{localStorage.setItem('hsk-lang',currentLang);}catch{}i18nTexts.forEach(([node,value])=>{node.nodeValue=t(value);});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===currentLang);b.setAttribute('aria-pressed',String(b.dataset.lang===currentLang));});renderSiteLists();renderRoute();}
const bannerSlides=()=>[...document.querySelectorAll('.banner-slide')];
function bannerGo(){showHome();}
function resetSlideTimer(){} // Single static banner; no autoplay timer.
function applyBanners(banners){bannerSlides().forEach((slide,i)=>{const setting=banners?.[i]||{};const image=mediaUrl(setting.image);slide.style.backgroundImage=image?'linear-gradient(90deg,rgba(255,255,255,.94),rgba(255,255,255,.35)),url('+JSON.stringify(image)+')':'';slide.style.backgroundSize='cover';slide.style.backgroundPosition='center';slide.querySelector('.hero-art').hidden=!!image;});}
function validContent(content){if(!content||typeof content!=='object'||Array.isArray(content)||content.site!=='hsk-portal'||content.version!==2)return false;for(const name of ['texts','lists','banners'])if(content[name]!=null&&(typeof content[name]!=='object'||Array.isArray(content[name])))return false;if(content.media!=null&&!Array.isArray(content.media))return false;for(const [name,list] of Object.entries(content.lists||{})){if(!Object.hasOwn(DEFAULT_LISTS,name)||!Array.isArray(list)||list.some(x=>!x||typeof x!=='object'||Array.isArray(x)))return false;}return true;}
function applySiteContent(content){if(!validContent(content))throw new Error('HSK 콘텐츠 형식(version 2, hsk-portal)이 아닙니다.');SITE_CONTENT=content;Object.keys(I18N).forEach(k=>delete I18N[k]);Object.assign(I18N,structuredClone(BASE_I18N));Object.keys(KO_OVERRIDE).forEach(k=>delete KO_OVERRIDE[k]);Object.entries(content.texts||{}).forEach(([key,v])=>{if(!v||typeof v!=='object')return;if(typeof v.ko==='string')KO_OVERRIDE[key]=v.ko;I18N[key]={...I18N[key],...(typeof v.en==='string'?{en:v.en}:{}),...(typeof v.zh==='string'?{zh:v.zh}:{})};});Object.keys(DEFAULT_LISTS).forEach(name=>LISTS[name]=content.lists?.[name]??structuredClone(DEFAULT_LISTS[name]));applyBanners(content.banners);setLang(currentLang);}
let cmsLoading=null;
function loadCMS(){if(window.CMS)return Promise.resolve(window.CMS);if(cmsLoading)return cmsLoading;cmsLoading=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='cms.js?v=2';script.onload=()=>resolve(window.CMS);script.onerror=()=>{cmsLoading=null;script.remove();reject(new Error('CMS load failed'));};document.head.append(script);});return cmsLoading;}
function openCMS(){loadCMS().then(c=>c.open()).catch(()=>alert(tx('관리 화면을 불러오지 못했습니다. 다시 시도해 주세요.','Could not load the content editor. Please try again.','无法加载内容管理，请重试。')));}
