let savedLang='ko';try{savedLang=localStorage.getItem('hsk-lang')||'ko';}catch{}setLang(new URLSearchParams(location.search).get('lang')||savedLang);
const emptyContent={version:2,site:'hsk-portal',texts:{},lists:{},banners:{},media:[]};
const siteContentReady=(async()=>{let content=emptyContent;try{if(location.protocol!=='file:'){const res=await fetch('content.json',{cache:'no-store'});if(!res.ok)throw new Error('Content HTTP '+res.status);const data=await res.json();if(!validContent(data))throw new Error('Invalid content schema');content=data;}}catch(error){console.warn('Published content unavailable; using built-in HSK guide.',error);const status=document.getElementById('siteStatus');status.hidden=false;status.textContent=tx('게시된 콘텐츠를 불러오지 못해 기본 안내를 표시합니다.','Published content could not be loaded. Showing the default guide.','无法加载已发布内容，现显示默认指南。');}applySiteContent(content);return content;})();
siteContentReady.then(()=>{try{if(localStorage.getItem('hsk2-cms-draft-v2'))loadCMS().then(c=>c.resumeDraft()).catch(console.error);}catch{}});
